export interface RequisitoClave {
  texto: string;
  cumple: boolean;
}

// Si cambia la regla, se cambia en los dos lados.
export function requisitosDeClave(clave: string): RequisitoClave[] {
  return [
    { texto: 'Entre 12 y 200 caracteres', cumple: clave.length >= 12 && clave.length <= 200 },
    { texto: 'Al menos una minúscula', cumple: /\p{Ll}/u.test(clave) },
    { texto: 'Al menos una mayúscula', cumple: /\p{Lu}/u.test(clave) },
    { texto: 'Al menos un carácter especial (como # ! - .)', cumple: /[^\p{L}\p{N}\s]/u.test(clave) },
    { texto: 'No puede ser solo espacios', cumple: !/^\s*$/u.test(clave) }
  ];
}

export function claveCumple(clave: string): boolean {
  return requisitosDeClave(clave).every((requisito) => requisito.cumple);
}
