import { claveCumple, requisitosDeClave } from './clave';

describe('reglas de contraseña de interfaz', () => {
  it('presenta en verde cada requisito cumplido', () => {
    expect(requisitosDeClave('Árbolñandú2026#').every((requisito) => requisito.cumple)).toBeTrue();
    expect(claveCumple('Árbolñandú2026#')).toBeTrue();
  });

  it('no acepta contraseñas cortas, sin mayúscula o con espacios únicamente', () => {
    expect(claveCumple('Aa1!1234567')).toBeFalse();
    expect(claveCumple('abcdefghijkl!')).toBeFalse();
    expect(claveCumple('           ')).toBeFalse();
  });
});
